{"implementation": "def solve(case):
    payload = case.get("payload")
    if payload is None:
        raise ValueError("Missing 'payload' in case")

    segments = payload.get("segments")
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError("'segments' must be a non-empty list")

    raw_budget = payload.get("budget")
    if raw_budget is None:
        raise ValueError("Missing 'budget' in payload")

    def _to_int(val, label):
        if isinstance(val, bool):
            raise ValueError(f"{label} must be an integer, got {val!r}")
        if isinstance(val, int):
            return val
        if isinstance(val, float) and val == int(val):
            return int(val)
        raise ValueError(f"{label} must be an integer, got {val!r}")

    budget = _to_int(raw_budget, "budget")

    names = []
    importances = []
    minimums = []
    capacities = []

    for idx, seg in enumerate(segments):
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in seg:
                raise ValueError(
                    f"Segment at index {idx} missing required field '{field}'"
                )
        name = seg["name"]
        imp = seg["importance"]
        mn = _to_int(seg["minimum"], f"segment '{name}' minimum")
        cap = _to_int(seg["capacity"], f"segment '{name}' capacity")

        if isinstance(imp, bool) or not isinstance(imp, (int, float)):
            raise ValueError(f"Segment '{name}': importance must be numeric")
        if mn < 0:
            raise ValueError(f"Segment '{name}': minimum must be >= 0")
        if cap < 0:
            raise ValueError(f"Segment '{name}': capacity must be >= 0")
        if mn > cap:
            raise ValueError(
                f"Segment '{name}': minimum ({mn}) exceeds capacity ({cap})"
            )

        names.append(name)
        importances.append(float(imp))
        minimums.append(mn)
        capacities.append(cap)

    n = len(segments)
    quota_sum = sum(minimums)
    capacity_sum = sum(capacities)

    if budget < quota_sum:
        raise ValueError(
            f"Budget {budget} is below minimum quota sum {quota_sum}"
        )
    if budget > capacity_sum:
        raise ValueError(
            f"Budget {budget} exceeds total capacity {capacity_sum}"
        )

    alloc = list(minimums)
    remaining = budget - quota_sum

    for _ in range(remaining):
        best_idx = -1
        best_priority = -1.0
        for i in range(n):
            if alloc[i] < capacities[i]:
                priority = importances[i] / (alloc[i] + 1)
                if priority > best_priority:
                    best_priority = priority
                    best_idx = i
        if best_idx == -1:
            raise ValueError(
                "Cannot allocate remaining budget: all segments at capacity"
            )
        alloc[best_idx] += 1

    allocations = {names[i]: alloc[i] for i in range(n)}
    name_mapping = {str(i): names[i] for i in range(n)}
    total = sum(alloc)

    return {
        "allocations": allocations,
        "name_mapping": name_mapping,
        "total": total,
    }
"}
